package com.nigson.experience.distributor;
import com.nigson.shared.observability.WireContext;import com.nigson.shared.problem.*;import com.nigson.shared.security.PrivateWorkload;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.bind.annotation.*;import tools.jackson.databind.JsonNode;
@RestController public final class DistributorController {private final DistributorService service;public DistributorController(DistributorService service){this.service=service;}private PrivateWorkload.Proof proof(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated())throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);if(!(a.getPrincipal() instanceof PrivateWorkload.Proof p))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return p;}private static UUID corr(){var w=WireContext.current();return w==null?WireContext.correlation(null):w.correlationId;}private static String header(HttpServletRequest r,String n){var h=Collections.list(r.getHeaders(n));if(h.size()!=1||h.getFirst().isBlank()||h.getFirst().length()>100)throw ApiValues.invalid();return h.getFirst();}private static void query(HttpServletRequest r,Set<String> allowed){r.getParameterMap().keySet().forEach(k->{if(!allowed.contains(k))throw ApiValues.invalid();});}
@PostMapping(value="/api/v1/distributor-applications",consumes="application/json",produces="application/json") public ResponseEntity<DistributorValues.Application> submit(HttpServletRequest r,@RequestBody JsonNode n){query(r,Set.of());var a=service.submit(proof(),DistributorValues.submission(n),header(r,"Idempotency-Key"),corr());return ResponseEntity.status(201).header("Cache-Control","no-store").eTag("\""+a.version()+"\"").body(a);}
@GetMapping(value="/api/v1/me/distributor-applications",produces="application/json") public ResponseEntity<List<DistributorValues.Application>> mine(HttpServletRequest r){query(r,Set.of());return ResponseEntity.ok().header("Cache-Control","no-store").body(service.mine(proof()));}
@GetMapping(value="/api/v1/staff/distributor-applications",produces="application/json") public ResponseEntity<DistributorValues.Page> queue(HttpServletRequest r,@RequestParam(required=false)String state,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="submittedAt,desc")String sort){query(r,Set.of("state","page","size","sort"));return ResponseEntity.ok().header("Cache-Control","no-store").body(service.queue(proof(),state,page,size,sort));}
@GetMapping(value="/api/v1/staff/distributor-applications/{id}",produces="application/json") public ResponseEntity<DistributorValues.Detail> detail(HttpServletRequest r,@PathVariable String id){query(r,Set.of());return ResponseEntity.ok().header("Cache-Control","no-store").body(service.detail(proof(),ApiValues.uuid(id)));}
@PostMapping(value="/api/v1/staff/distributor-applications/{id}/review",consumes="application/json",produces="application/json") public ResponseEntity<DistributorValues.Application> review(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode n){query(r,Set.of());long v=version(header(r,"If-Match"));if(!n.path("reason").isString()||!n.path("documentsVerified").isBoolean()||!n.propertyNames().equals(Set.of("reason","documentsVerified")))throw ApiValues.invalid();var a=service.review(proof(),ApiValues.uuid(id),n.path("reason").asString(),n.path("documentsVerified").asBoolean(),v,header(r,"Idempotency-Key"),corr());return ResponseEntity.ok().header("Cache-Control","no-store").eTag("\""+a.version()+"\"").body(a);}
@PostMapping(value="/api/v1/staff/distributor-applications/{id}/decision",consumes="application/json",produces="application/json") public ResponseEntity<DistributorValues.Application> decide(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode n){query(r,Set.of());long v=version(header(r,"If-Match"));var a=service.decide(proof(),ApiValues.uuid(id),DistributorValues.decision(n),header(r,"Idempotency-Key"),v,corr());return ResponseEntity.accepted().header("Cache-Control","no-store").eTag("\""+a.version()+"\"").body(a);}private static long version(String s){if(!s.matches("\"(0|[1-9][0-9]{0,18})\""))throw ApiValues.invalid();try{return Long.parseLong(s.substring(1,s.length()-1));}catch(Exception e){throw ApiValues.invalid();}}}
